import numpy as np

def mcts_select(node, exploration_c=1.4):
    total_visits = node.total_visits
    if total_visits == 0:
        return None
    best_action = None
    best_ucb = float("-inf")
    for action in node.available_actions:
        if action not in node.explored_actions:
            return None
        q = node.q_values.get(action, 0)
        n_sa = node.action_visits.get(action, 0)
        if n_sa == 0:
            return action
        ucb = q + exploration_c * np.sqrt(np.log(total_visits) / n_sa)
        if ucb > best_ucb:
            best_ucb = ucb
            best_action = action
    return best_action
